#!/usr/bin/env bash
# Chapitre « Les documents des membres » (partie Membres et collaboration) + sommaire.
# Prérequis : apply-bienvenue-avis-club.sh.
# Usage (racine du repo) : bash apply-docs-documents-membres.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/documents-des-membres.mdx" 2>/dev/null | grep -qF "title: \"Les documents des membres\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "sendWelcomeNotice" "packages/backend/src/modules/users/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-bienvenue-avis-club.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/membres/documents-des-membres.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Les documents des membres\"" "apps/web/content/docs/dev/membres/documents-des-membres.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/membres"
base64 -d > "apps/web/content/docs/dev/membres/documents-des-membres.mdx" <<'B64'
